"""Immutable real native ABA task with host-only expanded validation and retention."""
import hashlib,json,subprocess,sys
from pathlib import Path
from kali_qwen_aba_jobs_20261115 import ROOT,DATA,sha
TASK_NAME='kali-qwen-expanded46'
def baseline():
 grades=json.loads((DATA/'controls/score.json').read_text());assert grades['qwen_base']['eligible'] and abs(grades['qwen_base']['score'])<1e-8
 choices=[('E0',grades['qwen_base'])]
 if grades['qwen_fixed']['eligible']:choices.append(('fixedSFT256',grades['qwen_fixed']))
 cid,g=max(choices,key=lambda a:a[1]['score']);p={'schema':'kali.qwen.expanded46.v1','candidate_id':cid,'model_id':'Qwen/Qwen3-8B','model_revision':'b968826d9c46dd6066d109eabc6255188de91218','adapter_sha256':None if cid=='E0' else json.loads((DATA/'protocol.json').read_text())['fixed_comparator']['weights_sha256'],'optimizer_steps':0 if cid=='E0' else 256,'protocol_sha256':sha(DATA/'protocol.json')}
 record={'candidate_id':cid,'score':g['score'],'pointer':p,'scores':grades};path=DATA/'native-baseline-private.json';raw=json.dumps(record,indent=2)+'\n'
 if path.exists():assert path.read_text()==raw
 else:path.write_text(raw)
 return record

def build_task(out):
 out=Path(out);task=out/'task';task.mkdir();b=baseline();train=(DATA/'train-encoded-private.json').read_bytes();(out/'training-encoded-host-private.json').write_bytes(train)
 # Only TRAIN is readable by agents. No DEV input, gold, IDs or scorer source.
 rows=json.loads(train);preview=[{'id':r['id'],'origin':r['origin'],'prompt_tokens':r['prompt_tokens'],'target_tokens':r['target_tokens']} for r in rows[:8]];(task/'behavior_train_preview.jsonl').write_text(''.join(json.dumps(r)+'\n' for r in preview))
 manifest={'model_id':'Qwen/Qwen3-8B','model_revision':b['pointer']['model_revision'],'placement_sha256':sha(DATA/'placement-amendment-private.json'),'initialization':'ORIGINAL publisher weights for each candidate, never the fixed champion adapter','training_rows':256,'train_encoded_sha256':hashlib.sha256(train).hexdigest(),'origins':{'new_four_tool_silver':128,'publisher_replay':128},'quality':'AI authored local executable silver plus publisher rows,not expert gold','candidates':['A1','A2'],'learning_rates':[1e-5,3e-5,5e-5],'max_candidates':2,'max_updates_each':128,'max_new_updates_total':256,'fixed_comparator_updates':256,'microbatch':1,'accumulation':4,'epochs':2,'r':16,'alpha':32,'dropout':0,'target_modules':['q_proj','v_proj'],'seed':42,'KL':0,'protocol_sha256':sha(DATA/'protocol.json'),'fairness':'Two fresh128-step candidates versus cached fixed256-step SFT; equal total update budget,not equal selected steps or end-to-end wall/FLOPs. Data and loss unchanged.','official_TEST_rows':0}
 (task/'training_manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');(task/'base_model.json').write_text(json.dumps(b['pointer'],indent=2)+'\n');(task/'train_client.py').write_bytes((ROOT/'scripts/kali_qwen_aba_client_20261115.py').read_bytes());(task/'baseline_metrics.json').write_text(json.dumps({'existing_measured_baseline':True,'optimizer_steps':b['pointer']['optimizer_steps'],'new_steps_this_run':0},indent=2)+'\n')
 readme='''# Bounded native ABA on original Qwen3-8B
Use the supplied frozen host backend. This is an internal CLI/cybersecurity-adjacent pilot,not an official KaliBench result. The fixed champion in base_model.json is an actual measured baseline scored by the same host metric. Every new candidate starts from ORIGINAL publisher Qwen3-8B weights,never this champion adapter. Exactly two DISTINCT learning rates may be chosen from training_manifest.json. All other optimizer/data/generation settings are fixed;each candidate does128 fresh updates,for256 total,matching the existing fixed SFT total updates. This is bounded hyperparameter search,not autonomous data synthesis or a24-hour broad search. No candidate is cached/reused as fresh training.

Setup FIRST read setup_scaffold.md and use prepare_contract.py. Native deterministic verification and semantic review MUST run unchanged. No grader invention,training or submission during Setup or Designer. The plain public README and private scoring callable are materialized from approved answer-free constants. All validation labels and fixtures remain host-only.

Designer read ONLY README.md and training_manifest.json,then immediately propose exactly two DISTINCT concise plans,A1 and A2,each assigning a DIFFERENT allowed learning rate. requested_gpus=0 because the host dispatches an external GPU. No references,revisions,network checks,package installs or full TRAIN export during design. Worker may export the exact256 masked TRAIN rows if necessary using train_client.py export-train;no DEV labels are transferred.

Worker use unmodified train_client.py. In a Bash call set DATA_DIR=PUBLIC and OUTPUT_DIR=your artifacts/full;submit ONCE using python train_client.py submit --candidate A1 --lr 0.00001 (replace ID/LR with assigned plan). Submission is asynchronous. Call wait --candidate A1 --seconds420 in ONE Bash call with timeout600000;Python polls internally without using model turns. If IN_PROGRESS,repeat that same long wait;never duplicate submit. Backend may take up to2hours with queue. On REAL_GPU_TRAINING_COMPLETE use finalize with same candidate. Inspect final_model/model.json,train_metrics.json,run.py,README.md and submit those four real files. Never fake receipts,score candidates yourself,or access judge paths. Two candidates execute sequentially with one ordinary RTX3090 at a time. Host requires native Setup passed and an active native Worker before GPU dispatch.

PRIVATE metric score: mean over26 taskgroups of confirmed fixture PASS fraction in DEV46,minus E0 utility;plus0.25*(old64 native score-E0);minus10*(historical correct lost/13). UNKNOWN is unresolved,not semantic failure. A candidate must keep old64 native>=E0-2points,retain>=11/13 historical correct and>=80% fresh E0 correct,with no truncation/earlyEOS. Ineligible score=-100-lost-truncated. Larger is better. Native Score calls the host with a certified actual weight pointer. The baseline uses this same metric. Finalizer copies the four selected files preserving exact bytes. A separate host policy keeps the best eligible of E0,fixedSFT and nativewinner;ties retain existing model. No protected confirmation is used in selection.
'''
 (task/'README.md').write_text(readme)
 score='''import json,urllib.request
from pathlib import Path
def score(output_dir):
 pointer=json.loads((Path(output_dir)/'final_model/model.json').read_text());req=urllib.request.Request('http://127.0.0.1:29847/candidate',data=json.dumps({'action':'score','pointer':pointer}).encode(),headers={'Content-Type':'application/json'})
 with urllib.request.urlopen(req,timeout=100) as response:result=json.load(response)
 assert 'score' in result and result.get('status')!='FAILED'
 return result
'''
 model=(task/'base_model.json').read_text();metrics=(task/'baseline_metrics.json').read_text();bREADME='Existing actually measured E0/fixed SFT champion,0newupdates in native run.\n'
 baseline_source="import os,pathlib\nMODEL="+repr(model)+"\nMETRICS="+repr(metrics)+"\nREADME="+repr(bREADME)+"\nout=pathlib.Path(os.environ['OUTPUT_DIR']);(out/'final_model').mkdir(parents=True,exist_ok=True);(out/'final_model/model.json').write_text(MODEL);(out/'train_metrics.json').write_text(METRICS);(out/'README.md').write_text(README);(out/'run.py').write_bytes(pathlib.Path(__file__).read_bytes())\n"
 payload={'readme':readme,'model_text':model,'metrics_text':metrics,'score_py':score,'baseline_readme':bREADME,'baseline_source':baseline_source};(task/'setup_payload.json').write_text(json.dumps(payload,indent=2)+'\n');(task/'prepare_contract.py').write_bytes((ROOT/'scripts/kali8b_prepare_contract.py').read_bytes())
 old=ROOT/'scripts/build-kali8b-native-study.py';source=old.read_text();start=source.index(" (task/'setup_scaffold.md').write_text('''")+len(" (task/'setup_scaffold.md').write_text('''");end=source.index("''')",start);(task/'setup_scaffold.md').write_text(source[start:end])
 tmp=out/'config-template.json';subprocess.run([sys.executable,str(ROOT/'scripts/build-aba-synthetic-config.py'),'--remote-root','/mnt/aba-scratch/study','--output',str(tmp)],capture_output=True,check=True);config=json.loads(tmp.read_text());tmp.unlink();config['run']['task_name']=TASK_NAME;config['run']['budget'].update(wall_clock_minutes=240,cost_usd=15,per_agent_cost_cap_usd=6);config['llm']['default']['model']='deepseek-v4-flash';config['llm']['retry_ceiling_s']=45
 config['llm']['system_instructions']={'setup':'FIRST Read setup_scaffold.md. Symlink ONLY prepare_contract.py and setup_payload.json from TASK into PUBLIC with ln -s;execute helper --public-dir PUBLIC --private-dir PRIVATE;then immediately StructuredOutput(score,max). All native verification/review MUST run. No cp,shutil,grader invention,training,submissions or full TRAIN inspection. Keep baseline_metrics private.','designer':'Read ONLY README.md and training_manifest.json,then immediately submit two distinct plans A1/A2 with DIFFERENT learning rates from allowed list. No references,revisions,exports,training,submissions or environment checks. requested_gpus=0 for external backend.','worker':'Follow public README and unmodified train_client.py. Submit assigned candidate ONCE with chosen allowed --lr. DATA_DIR=PUBLIC OUTPUT_DIR=artifacts/full. wait --seconds420 in ONE Bash call timeout600000,without shelltimeout or model-turn polling everyminute. IN_PROGRESS normal:repeat longwait,no duplicate submit. On REAL_GPU_TRAINING_COMPLETE finalize,inspect fourfiles,submit genuine output. All candidates128newupdates from originalQwen. No grading access or synthetic results.','finalizer':'Copy selected final_model/model.json,train_metrics.json,run.py,README.md into deliverable byte-for-byte and immediately submit. No re-training,reconstruction or rescoring.'}
 config['search']['input'].update(parallel=1,num_designs=2,num_revisions=1,max_evaluations=2,early_stopping=2)
 for unit in config['work_units']:
  unit['budget']['minutes']=130 if unit['name'] in ['worker','training'] else 30 if unit['name']=='setup' else 15 if unit['name'] in ['designer','setup_review','finalizer'] else 5
  if unit['budget']['kind']=='pipeline':unit['budget'].pop('minutes',None)
 (out/'config.json').write_text(json.dumps(config,indent=2)+'\n');frozen={'baseline':b,'config_sha256':sha(out/'config.json'),'task_sha256':{p.name:sha(p) for p in task.iterdir()},'native_candidates_maximum':2,'no_confirmation_used':True,'runtime_source_sha256':{n:sha(ROOT/'scripts'/n) for n in ['run_kali_qwen_native_20261115.py','build_kali_qwen_native_20261115.py','kali_qwen_native_bridge_20261115.py','kali_qwen_aba_client_20261115.py','kali_qwen_aba_jobs_20261115.py','kali_qwen_aba_worker_20261115.py','kali_qwen_gpu_placement_20261115.py','kali_qwen_native_daemon_20261115.py','kali_qwen_native_supervisor_20261115.py','kali8b_native_install.sh','kali8b_native_vm.py','kali8b_native_journal.py','kali8b_native_mailbox.py','nrp_anthropic_transport.py','kali8b_prepare_contract.py']}};(out/'native-task-freeze-private.json').write_text(json.dumps(frozen,indent=2)+'\n');return config
